// Settings of the inference firmware.
// The model itself and its preprocessing constants are in model_data.h,
// which is generated by ml/convert_tflite.py.

#pragma once

#include <Arduino.h>

// ---- Sensor (I2C) ----
const int I2C_SDA_PIN = 8;
const int I2C_SCL_PIN = 9;
const uint8_t BME280_I2C_ADDRESS = 0x76;

// ---- Sampling ----
// Minutes between two sensor readings. The readings of each grid step
// (MODEL_GRID_MINUTES, 30 by default) are averaged, exactly like
// ml/prepare_dataset.py does, so use the same value as the logger.
const unsigned long SAMPLE_INTERVAL_MINUTES = 5;

// ---- Serial port ----
const unsigned long SERIAL_BAUD_RATE = 115200;

// ---- Clock ----
// How the node gets the date and time:
//   0 = serial command "SETTIME <epoch>"
//   1 = NTP over Wi-Fi at boot. Needs a file secrets.h with the Wi-Fi name
//       and password: copy secrets.example.h to secrets.h and edit it.
//       secrets.h is listed in .gitignore and must never be committed.
// The clock is LOST on reset or power loss. In the field without a PC, NTP
// is the only way to recover it automatically.
#define USE_WIFI_NTP 0

// Same servers and waiting time as firmware/logger (first answer took 16.5 s
// on the home network on 2026-11-20).
const char NTP_SERVER[] = "pool.ntp.org";
const char NTP_SERVER_2[] = "time.google.com";
const char NTP_SERVER_3[] = "time.cloudflare.com";
const unsigned long WIFI_TIMEOUT_MS = 15000;
const unsigned long NTP_TIMEOUT_MS = 30000;

// Local time zone (Colombia: UTC-5, no DST). Both values must agree.
const long UTC_OFFSET_SECONDS = -5 * 3600;
const char UTC_OFFSET_TEXT[] = "-05:00";

// ---- Reference temperature probe (DS18B20 on 1-Wire, optional) ----
// Same as in firmware/logger: only for calibration, not a model input.
#define USE_REFERENCE_PROBE 1
const int ONE_WIRE_PIN = 4;

// ---- Storage (flash, LittleFS) ----
// Every reading, same format as firmware/logger:
const char LOG_FILE_PATH[] = "/log.csv";
const char LOG_FILE_HEADER[] =
    "timestamp_iso,temperature_c,humidity_pct,pressure_hpa,reference_temperature_c,status";
// One row per prediction (values of the newest 30 min step):
const char PREDICTIONS_FILE_PATH[] = "/predictions.csv";
const char PREDICTIONS_FILE_HEADER[] =
    "timestamp_iso,temperature_c,humidity_pct,pressure_hpa,predicted_class,probabilities";

// ---- TensorFlow Lite Micro ----
// Memory reserved for the interpreter. Starting value chosen to be clearly
// larger than needed; BENCHMARK prints how many bytes are really used, and
// this number can then be reduced.
const int TENSOR_ARENA_BYTES = 16 * 1024;

// Number of inferences timed by the BENCHMARK command (R7 asks for >= 100)
const int BENCHMARK_RUNS = 200;

// ---- Power measurement (INA219, optional) ----
// The INA219 goes in series between the 5 V charger and the 5V pin of the
// board (see docs/hardware_setup.md). If it does not answer on the I2C bus,
// the benchmark simply skips the power lines.
const uint8_t INA219_I2C_ADDRESS = 0x40;
const int POWER_SAMPLES = 50;                       // readings averaged
const unsigned long POWER_SAMPLE_PERIOD_MS = 20;    // time between readings

// Set to 1 to run the benchmark automatically a few seconds after boot.
// Needed to measure power, because then the node is powered by the charger
// and no PC is connected. Read the saved report later with LASTBENCH.
#define RUN_BENCHMARK_AT_BOOT 0
const unsigned long BENCHMARK_AT_BOOT_DELAY_MS = 10000;
const char BENCHMARK_FILE_PATH[] = "/benchmark.txt";
